/* NJ Black Press Archive map. Data is generated by data/build_map_data.py. */

(function () {
    'use strict';

    const MAP_BOUNDS = [[38.35, -88.7], [42.1, -73.55]];
    const DEFAULT_CENTER = [40.4, -80.8];
    const DEFAULT_ZOOM = 6;
    const PLACEHOLDER_MAP_STATUS = 'The publication map could not load.';

    const elements = {
        slider: document.getElementById('decade-slider'),
        output: document.getElementById('decade-output'),
        allYears: document.getElementById('all-years'),
        summary: document.getElementById('map-summary'),
        locationList: document.getElementById('location-list'),
        unmappedList: document.getElementById('unmapped-list'),
        mappedTotal: document.getElementById('mapped-total'),
        map: document.getElementById('publication-map'),
    };

    let map;
    let markerLayer;
    let payload;
    let markerByLocation = new Map();
    let state = { decade: null, place: null };

    function escapeHtml(value) {
        return String(value ?? '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    function formatDecade(start, asOfYear) {
        if (start === null) return `All recorded years (through ${asOfYear})`;
        return start === 2020 && asOfYear < 2029 ? `2020s (through ${asOfYear})` : `${start}s`;
    }

    function formatYears(publication, asOfYear) {
        const founded = Number.isInteger(publication.yearFounded) ? publication.yearFounded : 'Year unknown';
        const ceased = Number.isInteger(publication.yearCeased) ? publication.yearCeased : `present (as of ${asOfYear})`;
        return `${founded}–${ceased}`;
    }

    function visibleInSelectedDecade(publication) {
        if (state.decade === null) return true;
        if (!Number.isInteger(publication.yearFounded)) return false;
        const decadeEnd = state.decade + 9;
        const recordEnd = Number.isInteger(publication.yearCeased)
            ? publication.yearCeased
            : payload.metadata.asOfYear;
        return publication.yearFounded <= decadeEnd && recordEnd >= state.decade;
    }

    function visibleLocations() {
        return payload.locations
            .map((location) => {
                const publications = location.publications.filter(visibleInSelectedDecade);
                return { ...location, publications };
            })
            .filter((location) => location.publications.length > 0)
            .sort((a, b) => b.publications.length - a.publications.length || a.label.localeCompare(b.label));
    }

    function countLabel(count) {
        return `${count} publication${count === 1 ? '' : 's'}`;
    }

    function mapStatus(text) {
        elements.summary.textContent = text;
    }

    function currentUrl() {
        const url = new URL(window.location.href);
        url.searchParams.set('decade', state.decade === null ? 'all' : String(state.decade));
        if (state.place) url.searchParams.set('place', state.place);
        else url.searchParams.delete('place');
        return `${url.pathname}${url.search}${url.hash}`;
    }

    function updateUrl() {
        window.history.replaceState({}, '', currentUrl());
    }

    function motionOptions() {
        const reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        return { animate: !reduced, duration: reduced ? 0 : 0.4 };
    }

    function popupContent(location) {
        const label = formatDecade(state.decade, payload.metadata.asOfYear);
        const records = location.publications.map((publication) => `
            <li>
                <a href="publication.html?id=${encodeURIComponent(publication.id)}">${escapeHtml(publication.name)}</a>
                <span class="record-years">${escapeHtml(formatYears(publication, payload.metadata.asOfYear))}</span>
            </li>
        `).join('');
        return `<section class="map-popup" aria-label="${escapeHtml(location.label)} publications">
            <h3>${escapeHtml(location.label)}</h3>
            <p>${escapeHtml(countLabel(location.publications.length))} visible in the ${escapeHtml(label)}.</p>
            <ul>${records}</ul>
        </section>`;
    }

    function setMarkerAccessibility(marker, location) {
        const element = marker.getElement();
        if (!element) return;
        element.setAttribute('role', 'button');
        element.setAttribute('tabindex', '0');
        element.setAttribute('aria-label', `${location.label}: ${countLabel(location.publications.length)}. Press Enter for the publication list.`);
        element.addEventListener('keydown', (event) => {
            if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                selectLocation(location.id, true);
            }
        });
    }

    function renderMarkers(locations) {
        markerLayer.clearLayers();
        markerByLocation = new Map();
        const label = formatDecade(state.decade, payload.metadata.asOfYear);

        locations.forEach((location) => {
            const selected = location.id === state.place;
            const marker = window.L.circleMarker([location.latitude, location.longitude], {
                radius: Math.min(20, 7 + Math.sqrt(location.publications.length) * 1.7),
                color: selected ? '#f1eadf' : '#f16b7e',
                weight: selected ? 3 : 2,
                fillColor: selected ? '#ca3553' : '#5f1d2b',
                fillOpacity: 0.94,
                className: 'publication-marker',
                keyboard: true,
            });
            marker.bindTooltip(`${escapeHtml(location.label)} · ${countLabel(location.publications.length)} · ${escapeHtml(label)}`, {
                direction: 'top',
                offset: [0, -8],
            });
            marker.bindPopup(popupContent(location), { maxWidth: 320, autoPanPadding: [24, 24] });
            marker.on('add', () => setMarkerAccessibility(marker, location));
            marker.on('click', () => selectLocation(location.id, true));
            marker.addTo(markerLayer);
            markerByLocation.set(location.id, marker);
        });
    }

    function renderLocationList(locations) {
        if (!locations.length) {
            elements.locationList.innerHTML = '<li class="empty-state">No publication with a saved map location published during this decade.</li>';
            return;
        }
        elements.locationList.innerHTML = locations.map((location) => {
            const selected = location.id === state.place;
            return `<li>
                <button type="button" data-location-id="${escapeHtml(location.id)}" aria-pressed="${selected}">
                    <span class="location-list__name">${escapeHtml(location.label)}</span>
                    <span class="location-count">${escapeHtml(countLabel(location.publications.length))}</span>
                </button>
            </li>`;
        }).join('');
        elements.locationList.querySelectorAll('[data-location-id]').forEach((button) => {
            button.addEventListener('click', () => selectLocation(button.dataset.locationId, true));
        });
    }

    function renderUnmapped() {
        if (!payload.unmapped.length) {
            elements.unmappedList.innerHTML = '<li class="empty-state">Every publication has a saved map point.</li>';
            return;
        }
        elements.unmappedList.innerHTML = payload.unmapped.map((publication) => `
            <li>
                <a href="publication.html?id=${encodeURIComponent(publication.id)}">${escapeHtml(publication.name)}</a>
                <span>${escapeHtml(publication.city || 'Location unknown')} · ${escapeHtml(publication.reason)}</span>
            </li>
        `).join('');
    }

    function render() {
        const locations = visibleLocations();
        if (state.place && !locations.some((location) => location.id === state.place)) state.place = null;

        const count = locations.reduce((total, location) => total + location.publications.length, 0);
        const label = formatDecade(state.decade, payload.metadata.asOfYear);
        elements.output.textContent = label;
        elements.slider.setAttribute('aria-valuetext', label);
        elements.allYears.setAttribute('aria-pressed', String(state.decade === null));
        mapStatus(`${countLabel(count)} in ${locations.length} mapped location${locations.length === 1 ? '' : 's'} are visible for ${label}.`);
        renderMarkers(locations);
        renderLocationList(locations);

        if (state.place) {
            const selected = locations.find((location) => location.id === state.place);
            const marker = markerByLocation.get(state.place);
            if (selected && marker) marker.openPopup();
        }
    }

    function selectLocation(locationId, moveMap) {
        const location = visibleLocations().find((item) => item.id === locationId);
        if (!location) return;
        state.place = location.id;
        updateUrl();
        render();
        if (moveMap) {
            map.flyTo([location.latitude, location.longitude], Math.max(map.getZoom(), 10), motionOptions());
        }
    }

    function setDecade(decade) {
        state.decade = decade;
        state.place = null;
        if (decade !== null) elements.slider.value = String(decade);
        updateUrl();
        render();
    }

    function setInitialState() {
        const params = new URLSearchParams(window.location.search);
        const requested = params.get('decade');
        const first = payload.metadata.firstDecade;
        const last = payload.metadata.lastDecade;
        const numeric = Number(requested);
        state.decade = requested === 'all'
            ? null
            : Number.isInteger(numeric) && numeric >= first && numeric <= last && (numeric - first) % 10 === 0
                ? numeric
                : last;
        const requestedPlace = params.get('place');
        state.place = payload.locations.some((location) => location.id === requestedPlace) ? requestedPlace : null;
        elements.slider.min = String(first);
        elements.slider.max = String(last);
        elements.slider.value = String(state.decade === null ? last : state.decade);
    }

    function initializeMap() {
        map = window.L.map(elements.map, {
            center: DEFAULT_CENTER,
            zoom: DEFAULT_ZOOM,
            maxBounds: MAP_BOUNDS,
            maxBoundsViscosity: 0.85,
            minZoom: 5,
            zoomControl: true,
        });
        window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            maxZoom: 19,
            attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>',
        }).addTo(map);
        markerLayer = window.L.layerGroup().addTo(map);
        const points = payload.locations.map((location) => [location.latitude, location.longitude]);
        map.fitBounds(points, { padding: [28, 28] });
    }

    function bindControls() {
        elements.slider.addEventListener('input', () => setDecade(Number(elements.slider.value)));
        elements.allYears.addEventListener('click', () => setDecade(state.decade === null ? payload.metadata.lastDecade : null));
        window.addEventListener('popstate', () => {
            setInitialState();
            render();
        });
    }

    function reportFailure(error) {
        console.error('Publication map:', error);
        elements.map.textContent = PLACEHOLDER_MAP_STATUS;
        elements.map.classList.add('empty-state');
        mapStatus(PLACEHOLDER_MAP_STATUS);
    }

    async function init() {
        try {
            if (!window.L) throw new Error('Leaflet did not load');
            const response = await fetch('data/map-publications.json');
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            payload = await response.json();
            if (!Array.isArray(payload.locations) || !payload.metadata) throw new Error('Invalid map data');
            setInitialState();
            initializeMap();
            bindControls();
            renderUnmapped();
            elements.mappedTotal.textContent = String(payload.metadata.mappedPublicationCount);
            render();
            window.requestAnimationFrame(() => map.invalidateSize());
        } catch (error) {
            reportFailure(error);
        }
    }

    init();
}());
